create table public.erp_roles (id uuid primary key default gen_random_uuid(), name text unique not null, system_key text unique, created_at timestamptz not null default now());
grant select on public.erp_roles to authenticated; grant all on public.erp_roles to service_role;
alter table public.erp_roles enable row level security;
create policy "roles readable by staff" on public.erp_roles for select to authenticated using (true);
create table public.erp_role_permissions (role_id uuid not null references public.erp_roles(id) on delete cascade, permission text not null, primary key(role_id,permission));
grant select on public.erp_role_permissions to authenticated; grant all on public.erp_role_permissions to service_role;
alter table public.erp_role_permissions enable row level security;
create table public.erp_departments (id uuid primary key default gen_random_uuid(), name text not null unique);
grant select on public.erp_departments to authenticated; grant all on public.erp_departments to service_role;
alter table public.erp_departments enable row level security;
create policy "departments readable" on public.erp_departments for select to authenticated using (true);
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', language text not null default 'en' check(language in ('en','my','zh')), department_id uuid references public.erp_departments(id), team text not null default '', created_at timestamptz not null default now());
grant select on public.profiles to authenticated; grant all on public.profiles to service_role;
alter table public.profiles enable row level security;
create policy "own profile readable" on public.profiles for select to authenticated using (id=auth.uid() or public.has_role(auth.uid(),'admin'));
create table public.erp_staff_roles (user_id uuid primary key references public.profiles(id) on delete cascade, role_id uuid not null references public.erp_roles(id), active boolean not null default true, is_leader boolean not null default false, rep_id bigint unique references public.sales_reps(id));
grant select on public.erp_staff_roles to authenticated; grant all on public.erp_staff_roles to service_role;
alter table public.erp_staff_roles enable row level security;
create policy "own staff role readable" on public.erp_staff_roles for select to authenticated using (user_id=auth.uid() or public.has_role(auth.uid(),'admin'));
create policy "own permissions readable" on public.erp_role_permissions for select to authenticated using (exists(select 1 from public.erp_staff_roles s where s.user_id=auth.uid() and s.active and s.role_id=erp_role_permissions.role_id) or public.has_role(auth.uid(),'admin'));
create or replace function public.erp_has_permission(p_user uuid,p_permission text) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.erp_staff_roles s join public.erp_role_permissions p on p.role_id=s.role_id where s.user_id=p_user and s.active and p.permission=p_permission) $$;
grant execute on function public.erp_has_permission(uuid,text) to authenticated, service_role;
create or replace function public.create_erp_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict(id) do nothing; return new; end $$;
create trigger on_auth_user_erp_profile after insert on auth.users for each row execute function public.create_erp_profile();
insert into public.profiles(id) select id from auth.users on conflict(id) do nothing;
create table public.erp_areas (id bigint generated by default as identity primary key, name text not null unique);
grant select on public.erp_areas to authenticated; grant all on public.erp_areas to service_role;
alter table public.erp_areas enable row level security;
create policy "areas readable by staff" on public.erp_areas for select to authenticated using (exists(select 1 from public.erp_staff_roles s where s.user_id=auth.uid() and s.active));
create table public.erp_audit (id bigint generated by default as identity primary key, actor_id uuid not null, action text not null, subject text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
grant select on public.erp_audit to authenticated; grant all on public.erp_audit to service_role;
alter table public.erp_audit enable row level security;
create policy "audit permission" on public.erp_audit for select to authenticated using(public.erp_has_permission(auth.uid(),'audit.view'));
grant usage,select on sequence public.erp_areas_id_seq,public.erp_audit_id_seq to service_role;